{ 1-知行多空线（黄线）逻辑 }
M1:=14;
M2:=28;
M3:=57;
M4:=114;
知行短期趋势线:=EMA(EMA(C,10),10),COLORFFFFFF,LINETHICK1;
知行多空线:=(MA(CLOSE,M1)+MA(CLOSE,M2)+MA(CLOSE,M3)+MA(CLOSE,M4))/4;
白线达标:=知行短期趋势线>知行多空线;
黄线达标:=CLOSE>知行多空线;
趋势达标:=白线达标 AND 黄线达标;

{ 2-砖型图数据计算 }
VAR1A:=(HHV(HIGH,4)-CLOSE)/(HHV(HIGH,4)-LLV(LOW,4))*100-90;
VAR2A:=SMA(VAR1A,4,1)+100;
VAR3A:=(CLOSE-LLV(LOW,4))/(HHV(HIGH,4)-LLV(LOW,4))*100;
VAR4A:=SMA(VAR3A,6,1);
VAR5A:=SMA(VAR4A,6,1)+100;
VAR6A:=VAR5A-VAR2A;
砖型图:=IF(VAR6A>4,VAR6A-4,0);

{ 3-柱体颜色逻辑和高度逻辑 }
今天红柱:=砖型图 > REF(砖型图,1);
昨天绿柱:=REF(砖型图,1) < REF(砖型图,2);
前天绿柱:=REF(砖型图,2) < REF(砖型图,3);
大前天绿柱:=REF(砖型图,3) < REF(砖型图,4);
大前前天绿柱:=REF(砖型图,4) < REF(砖型图,5);
红柱高度:=砖型图 - REF(砖型图,1);
绿柱高度:=REF(砖型图,2) - REF(砖型图,1);
连续三绿:=昨天绿柱 AND 前天绿柱 AND 大前天绿柱;
连续四绿:=昨天绿柱 AND 前天绿柱 AND 大前天绿柱 AND 大前前天绿柱;
高度达标:=红柱高度 >= 绿柱高度 * 2 / 3;

{ 4-市值剔除 }
SZ:=CAPITAL/100*C/10000;
市值剔除:=SZ>50;

{ 5-板块剔除 }
剔除创业板:=IF(CODELIKE('300') OR CODELIKE('301'),0,1);
剔除科创:=IF(CODELIKE('688'),0,1);
剔除ST:=NOT(NAMELIKE('ST')) AND NOT(NAMELIKE('*ST'));
板块剔除:=剔除创业板 AND 剔除科创 AND 剔除ST;

{ 6-最终选股条件 }
综合选股: 趋势达标 AND 今天红柱 AND 昨天绿柱 AND 连续三绿 AND 高度达标 AND 市值剔除 AND 板块剔除;

